// TypeScript interfaces
export interface PricingTableSevenPlan {
  id: string;
  name: string;
  description: string;
  price: number;
  users: number;
  popular?: boolean;
}

export interface FeatureItemRecord {
  name: string;
  tooltip?: boolean;
  [planId: string]: boolean | string | undefined;
}

export interface FeatureCategory {
  category: string;
  items: FeatureItemRecord[];
}

export interface PricingTableSevenProps extends VariantProps<
  typeof sectionVariants
> {
  plans: PricingTableSevenPlan[];
  features: FeatureCategory[];
  title?: string;
  description?: string;
  onPlanSelect?: (planId: string) => void;
  className?: string;
}

export function PricingTableSeven({
  className,
  plans,
  features,
  title = "Choose a plan that's right for you",
  description = "We believe Untitled should be accessible to all companies, no matter the size of your startup.",
  onPlanSelect,
  size,
  theme = "minimal",
}: PricingTableSevenProps) {
  const [selectedPlan, setSelectedPlan] = useState(
    plans.find((p) => p.popular)?.id || plans[0]?.id || "",
  );

  const [sliderValue, setSliderValue] = useState<number[]>([
    plans.find((p) => p.popular)?.users || 0,
  ]);

  const renderFeatureValue = (value: boolean | string | undefined) => {
    if (typeof value === "boolean") {
      return value ? (
        <Check className="text-primary h-5 w-5" />
      ) : (
        <span className="text-muted-foreground">—</span>
      );
    }
    if (typeof value === "string") {
      return <span className="text-foreground text-sm">{value}</span>;
    }
    return <span className="text-muted-foreground">—</span>;
  };

  const handlePlanSelect = (planId: string) => {
    setSelectedPlan(planId);
    const selected = plans.find((p) => p.id === planId);
    if (selected && typeof selected.users === "number") {
      setSliderValue([selected.users]);
    }
    onPlanSelect?.(planId);
  };

  return (
    <section className={cn(sectionVariants({ size, theme }), className)}>
      {/* Classic theme background elements */}
      {theme === "classic" && (
        <>
          <div className="bg-grid-pattern absolute inset-0 opacity-5" />
          <div className="bg-primary/5 absolute top-1/2 left-1/2 h-96 w-96 -translate-x-1/2 -translate-y-1/2 rounded-full blur-3xl" />
          <div className="bg-secondary/5 absolute top-1/4 right-1/4 h-64 w-64 rounded-full blur-2xl" />
        </>
      )}

      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Hero Section */}
        <div className="pb-1 text-center">
          <h1 className={cn(titleVariants({ size, theme }), "leading-[1.12]")}>
            {title}
          </h1>
          <p className={cn(descriptionVariants({ size, theme }), "mt-6")}>
            {description}
          </p>
        </div>

        {/* User Slider */}
        <div className="mx-auto mt-12 max-w-md px-4">
          <div className="relative">
            <Slider
              value={sliderValue}
              onValueChange={(e) => {
                setSliderValue(e);
                setSelectedPlan(
                  plans.filter((plan) => plan.users >= e[0])[0]?.id ||
                    plans.find((plan) => plan.popular)?.id!,
                );
              }}
              max={25}
              min={1}
              step={1}
              className="text-primary w-full"
            />
            <div className="mt-2 text-center">
              <span className="text-foreground text-sm font-medium">
                {sliderValue[0]} users
              </span>
            </div>
          </div>
        </div>

        {/* Pricing Cards */}
        <div className="mt-16">
          <div className="mb-8 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {plans.map((plan) => (
              <motion.div
                key={plan.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
              >
                <Card
                  className={cn(
                    cardVariants({
                      size,
                      theme,
                      selected: selectedPlan === plan.id,
                    }),
                  )}
                  onClick={() => handlePlanSelect(plan.id)}
                >
                  {plan.popular && (
                    <Badge
                      className={cn(
                        "absolute -top-3 left-1/2 z-10 -translate-x-1/2 px-4 py-1 text-sm font-medium shadow-lg",
                        theme === "classic"
                          ? "from-primary to-primary/80 text-primary-foreground border-primary/20 bg-gradient-to-r"
                          : "bg-primary text-primary-foreground",
                      )}
                    >
                      Most popular
                    </Badge>
                  )}
                  <CardHeader className="text-center">
                    <CardTitle className="text-lg font-semibold">
                      {plan.name}
                    </CardTitle>
                    <CardDescription className="text-muted-foreground text-sm">
                      {plan.description}
                    </CardDescription>
                    <div className="mt-4">
                      <span
                        className={cn(
                          "text-4xl font-bold",
                          theme === "classic"
                            ? "from-foreground to-muted-foreground bg-gradient-to-r bg-clip-text text-transparent"
                            : "text-foreground",
                        )}
                      >
                        ${plan.price}
                      </span>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <Button
                      className={cn(
                        buttonVariants({
                          theme,
                          selected: selectedPlan === plan.id,
                        }),
                      )}
                    >
                      Get started
                    </Button>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </div>

          {/* Feature Comparison Table */}
          <div
            className={cn(
              "overflow-hidden overflow-x-auto rounded-lg border",
              theme === "classic"
                ? "bg-card/50 border-border/50 shadow-md backdrop-blur-sm"
                : "bg-card",
            )}
          >
            <AnimatePresence>
              {features.map((category, categoryIndex) => (
                <motion.div
                  key={category.category}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.3, delay: categoryIndex * 0.1 }}
                >
                  {categoryIndex > 0 && <div className="border-t" />}

                  {/* Category Header */}
                  <div
                    className={cn(
                      "px-4 py-4 sm:px-6",
                      theme === "classic" ? "bg-muted/30" : "bg-muted/50",
                    )}
                  >
                    <h3 className="text-foreground text-sm font-semibold">
                      {category.category}
                    </h3>
                  </div>

                  {/* Feature Rows */}
                  {category.items.map((feature, featureIndex) => (
                    <div
                      key={feature.name}
                      className={cn(
                        "px-4 py-4 sm:px-6",
                        featureIndex > 0 && "border-border/50 border-t",
                      )}
                    >
                      {/* Mobile Layout */}
                      <div className="block sm:hidden">
                        <div className="mb-3 flex items-center space-x-2">
                          <span className="text-foreground text-sm font-medium">
                            {feature.name}
                          </span>
                          {feature.tooltip && (
                            <Info className="text-muted-foreground h-4 w-4" />
                          )}
                        </div>
                        <div className="space-y-2">
                          {plans.map((plan) => (
                            <div
                              key={plan.id}
                              className="flex items-center justify-between"
                            >
                              <span className="text-muted-foreground text-sm">
                                {plan.name}
                              </span>
                              <div className="flex items-center">
                                {renderFeatureValue(feature[plan.id])}
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Desktop Layout - Match pricing cards grid */}
                      <div className="hidden gap-4 sm:grid sm:grid-cols-[minmax(0,1.5fr)_repeat(3,minmax(0,1fr))] lg:grid-cols-4">
                        <div className="flex items-center space-x-2">
                          <span className="text-foreground text-sm font-medium">
                            {feature.name}
                          </span>
                          {feature.tooltip && (
                            <Info className="text-muted-foreground h-4 w-4" />
                          )}
                        </div>
                        {plans.map((plan) => (
                          <div
                            key={plan.id}
                            className="flex items-center justify-center"
                          >
                            {renderFeatureValue(feature[plan.id])}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </motion.div>
              ))}
            </AnimatePresence>
          </div>

          {/* Bottom CTA Buttons */}
          <div className="mt-8 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {plans.map((plan) => (
              <Button
                key={plan.id}
                className={cn(
                  buttonVariants({ theme, selected: selectedPlan === plan.id }),
                )}
                onClick={() => handlePlanSelect(plan.id)}
              >
                Get started
              </Button>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

