                                handleOpenChange(false);
                              }}
                            >
                              {selectedPlan === currentPlan.id
                                ? "Current Plan"
                                : "Upgrade"}
                            </Button>
                          </motion.div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
                ))}
              </div>
            </RadioGroup>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

