                          ? `${plan.currency}${getCurrentPrice(plan)}`
                          : getCurrentPrice(plan)}
                      </div>
                      <div className="text-muted-foreground mt-0.5 text-[10px] sm:text-xs">
                        /{isYearly ? "year" : "month"}
                      </div>
                    </div>
                  </div>
                </motion.div>

                <AnimatePresence initial={false}>
                  {selectedPlan === plan.id && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{
                        height: "auto",
                        opacity: 1,
                        transition: {
                          height: { duration: 0.3, ease: easing },
                          opacity: {
                            duration: 0.25,
                            delay: 0.05,
                            ease: easing,
                          },
                        },
                      }}
                      exit={{
                        height: 0,
                        opacity: 0,
                        transition: {
                          height: { duration: 0.25, ease: easing },
                          opacity: { duration: 0.15, ease: easing },
                        },
                      }}
                      className="overflow-hidden"
                    >
                      <motion.div
                        initial={{ y: -8 }}
                        animate={{
                          y: 0,
                          transition: {
                            duration: 0.25,
                            delay: 0.05,
                            ease: easing,
                          },
                        }}
                        exit={{ y: -8 }}
                        className="px-3 pb-3 sm:px-4 sm:pb-4"
                      >
                        <Button
                          className="h-10 w-full touch-manipulation text-sm font-medium sm:h-11 sm:text-base"
                          disabled={selectedPlan === currentPlan.id}
                          onClick={(e) => {
                            e.stopPropagation();
                            onPlanChange(plan.id);
                          }}
                        >
                          {selectedPlan === currentPlan.id
                            ? "Current Plan"
                            : "Upgrade"}
                        </Button>
                      </motion.div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            ))}
          </div>
        </RadioGroup>
      </CardContent>
    </Card>
  );
}

