          exit: { opacity: 0, scale: 0.95, y: -20 },
        };
      default:
        return {
          initial: { opacity: 0, y: -12 },
          animate: { opacity: 1, y: 0 },
          exit: { opacity: 0, y: -12 },
        };
    }
  };

  return (
